#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"#include "..\UniLogic.h"//// Обработка логики//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~typedef struct : public SPROLOZ  {  int  nType;  UINT nPlaceIF;  UINT nCountIF;  } Queue_Logic;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintLogic(DefinePaint)  {  QueueM(Queue_Logic);  if ( u != NULL )  switch ( p->nType )    {    case 0:      {      bool v = u->Visible( *q.m_pPipe, p->nCountIF, p->nPlaceIF );      u->If(v);      }      break;    case 1:      {      bool v = u->Visible( *q.m_pPipe, p->nCountIF, p->nPlaceIF );      u->ElseIf(v);      }      break;    case 2: u->Else ();break;    case 3: u->EndIf();break;    }  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddIf(DefineTegs)  {  AddQueueEx(Queue_Logic);  // Определение функции вывода  p->paint = &PaintLogic;  p->nType = 0;  p->btSendType = QUEUE_LOGIC;  char szObj[32] = "\0";  STegObj obj[] =    {    { 'S', "obj"  , szObj,31},    // Дополнительная информация    EXT_QUEUE    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  UINT eType  = TextToType( szObj );  p->nPlaceIF = rLog.AddCurr(0);  p->nCountIF = rLog.ParserIf( *def.m_queue.m_pPipe, eType, teg[0].value );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddElseIf(DefineTegs)  {  AddQueueEx(Queue_Logic);  // Определение функции вывода  p->paint = &PaintLogic;  p->nType = 1;  p->btSendType = QUEUE_LOGIC;  char szObj[32] = "\0";  STegObj obj[] =    {    { 'S', "obj"  , szObj,31},    // Дополнительная информация    EXT_QUEUE    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  UINT eType  = TextToType( szObj );  p->nPlaceIF = rLog.AddCurr(0);  p->nCountIF = rLog.ParserIf( *def.m_queue.m_pPipe, eType, teg[0].value );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddElse(DefineTegs)  {  AddQueueEx(Queue_Logic);  // Определение функции вывода  p->paint = &PaintLogic;  p->nType = 2;  p->btSendType = QUEUE_LOGIC;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddEndIf(DefineTegs)  {  AddQueueEx(Queue_Logic);  // Определение функции вывода  p->paint = &PaintLogic;  p->nType = 3;  p->btSendType = QUEUE_LOGIC;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~